            Event::RemoveBannedContent { .. } => Some(JobKind::RemoveBannedContent),
            Event::PurgeBlob { .. } => Some(JobKind::PurgeBlob),
            Event::DisconnectUser { .. } => None,
        }
    }

    /// The Rails job class, for logs.
    pub fn name(self) -> &'static str {
