        Ok(Ok(())) => tracing::info!(job = name, "performed"),
        Ok(Err(error)) => tracing::error!(job = name, error = %format_args!("{error:#}"), "job failed"),
        Err(panic) => tracing::error!(job = name, panic = panic_message(&*panic), "job panicked"),
    }
}

