                tx.emit_after_commit(Event::BotJoined { room_id: room.id, user_id });
            }
        }
    }
    Ok(())
}

/// The bots' users among `user_ids`, in that order.
fn bots_among(conn: &Connection, user_ids: &[i64]) -> Result<Vec<i64>> {
    if user_ids.is_empty() {
        return Ok(Vec::new());
    }
    let sql = format!(r#"SELECT "bots"."user_id" FROM "bots" WHERE "bots"."user_id" IN ({})"#, placeholders(user_ids.len()));
    let bots: Vec<i64> = query_all(conn, &sql, rusqlite::params_from_iter(user_ids), |r| r.get(0))?;
    Ok(user_ids.iter().copied().filter(|id| bots.contains(id)).collect())
}

